// Independent CPU checker: no CUDA headers and no original/native solver source.
#include <fstream>
#include <vector>
#include <cmath>
#include <cstring>
#include <cstdint>
#include <limits>
#include <iostream>
#include <iomanip>
#include <stdexcept>
#include <algorithm>
struct Rating{int32_t u,v;float r;};
template<class T>std::vector<T>read(std::ifstream&f,size_t n){std::vector<T>x(n);f.read((char*)x.data(),n*sizeof(T));if(!f)throw std::runtime_error("shortfile");return x;}
float decode_half(uint16_t h){unsigned exponent=(h>>10)&31,mantissa=h&1023;float v;if(exponent==31)v=mantissa?std::numeric_limits<float>::quiet_NaN():std::numeric_limits<float>::infinity();else if(exponent==0)v=std::ldexp(float(mantissa),-24);else v=std::ldexp(float(1024+mantissa),int(exponent)-25);return std::copysign(v,(h&32768)?-1.f:1.f);}
uint32_t bits(float v){uint32_t b;std::memcpy(&b,&v,4);return b;}
struct Fixture{int m,n,k;long long nr,nt;std::vector<float>parameters;std::vector<int32_t>pm,qm;std::vector<Rating>test;std::vector<uint16_t>initialP,initialQ;};
Fixture load(const char*name){std::ifstream f(name,std::ios::binary);auto magic=read<uint32_t>(f,2);if(magic[0]!=0x4d465331||magic[1]!=1)throw std::runtime_error("fixturemagic");auto h=read<int32_t>(f,4);auto count=read<int64_t>(f,2);Fixture x;x.m=h[0];x.n=h[1];x.k=h[2];x.nr=count[0];x.nt=count[1];x.parameters=read<float>(f,9);x.pm=read<int32_t>(f,x.m);x.qm=read<int32_t>(f,x.n);read<int32_t>(f,x.m+x.n);read<Rating>(f,x.nr);x.test=read<Rating>(f,x.nt);x.initialP=read<uint16_t>(f,size_t(x.m)*x.k);x.initialQ=read<uint16_t>(f,size_t(x.n)*x.k);return x;}
long double gamma(long double unit,size_t n){return n*unit/(1-n*unit);}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("fixture originaltrain science required");static_assert(sizeof(Rating)==12,"ratinglayout");Fixture x=load(argv[1]);std::ifstream train_file(argv[2],std::ios::binary);auto train=read<Rating>(train_file,x.nr);std::ifstream f(argv[3],std::ios::binary);auto h=read<int32_t>(f,8);auto parameters=read<float>(f,9);if(h[0]!=0x4d464d31||h[1]!=x.m||h[2]!=x.n||h[3]!=x.k||h[5]!=30||h[6]!=x.nr||h[7]!=x.nt||std::memcmp(parameters.data(),x.parameters.data(),36))throw std::runtime_error("scienceheader");size_t np=size_t(x.m)*x.k,nq=size_t(x.n)*x.k;auto halfP=read<uint16_t>(f,np),halfQ=read<uint16_t>(f,nq);auto beforeP=read<float>(f,np),beforeQ=read<float>(f,nq),P=read<float>(f,np),Q=read<float>(f,nq);auto predictions=read<double>(f,x.nr),heldout=read<double>(f,x.nt);if(f.peek()!=EOF)throw std::runtime_error("sciencetail");size_t half_conversion_failures=0,scale_permutation_failures=0,nonfinite=0;float factor=float(sqrtl((long double)x.parameters[0]));std::vector<float>initialP(np),initialQ(nq);for(size_t i=0;i<np;i++){half_conversion_failures+=bits(beforeP[i])!=bits(decode_half(halfP[i]));nonfinite+=!std::isfinite(beforeP[i])||!std::isfinite(P[i]);}for(size_t i=0;i<nq;i++){half_conversion_failures+=bits(beforeQ[i])!=bits(decode_half(halfQ[i]));nonfinite+=!std::isfinite(beforeQ[i])||!std::isfinite(Q[i]);}for(int row=0;row<x.m;row++)for(int j=0;j<x.k;j++){size_t dst=size_t(row)*x.k+j,src=size_t(x.pm[row])*x.k+j;float expected=float(double(decode_half(halfP[src]))*double(factor));scale_permutation_failures+=bits(expected)!=bits(P[dst]);initialP[dst]=float(double(decode_half(x.initialP[src]))*double(factor));}for(int row=0;row<x.n;row++)for(int j=0;j<x.k;j++){size_t dst=size_t(row)*x.k+j,src=size_t(x.qm[row])*x.k+j;float expected=float(double(decode_half(halfQ[src]))*double(factor));scale_permutation_failures+=bits(expected)!=bits(Q[dst]);initialQ[dst]=float(double(decode_half(x.initialQ[src]))*double(factor));}long double max_abs=0,max_fraction=0,train_error=0,initial_error=0,test_error=0;size_t prediction_failures=0,checked=0;long double u64=ldexpl(1.L,-53),uoracle=ldexpl(1.L,-std::numeric_limits<long double>::digits);auto evaluate=[&](const std::vector<Rating>&rows,const std::vector<double>&actual,bool is_train){for(size_t at=0;at<rows.size();at++){auto r=rows[at];if(r.u<0||r.u>=x.m||r.v<0||r.v>=x.n)throw std::runtime_error("ratingindex");long double sum=0,abs_sum=0,initial=0;for(int j=0;j<x.k;j++){long double product=(long double)P[size_t(r.u)*x.k+j]*(long double)Q[size_t(r.v)*x.k+j];sum+=product;abs_sum+=fabsl(product);if(is_train)initial+=(long double)initialP[size_t(r.u)*x.k+j]*(long double)initialQ[size_t(r.v)*x.k+j];}long double budget=(gamma(u64,x.k)+gamma(uoracle,x.k))*abs_sum+8*u64*std::max(1.L,fabsl(sum));long double error=fabsl((long double)actual[at]-sum);prediction_failures+=!std::isfinite(actual[at])||error>budget;max_abs=std::max(max_abs,error);max_fraction=std::max(max_fraction,error/budget);long double residual=sum-r.r;if(is_train){train_error+=residual*residual;long double e=initial-r.r;initial_error+=e*e;}else test_error+=residual*residual;checked++;}};evaluate(train,predictions,true);evaluate(x.test,heldout,false);long double rmse=sqrtl(test_error/x.nt);bool changed=halfP!=x.initialP||halfQ!=x.initialQ;bool valid=!half_conversion_failures&&!scale_permutation_failures&&!nonfinite&&!prediction_failures&&changed&&train_error<initial_error&&rmse<=3;std::cout<<std::setprecision(21)<<"{\"pass\":"<<(valid?"true":"false")<<",\"workers\":"<<h[4]<<",\"epochs\":30,\"half_to_float_values_checked\":"<<np+nq<<",\"scale_unshuffle_values_checked\":"<<np+nq<<",\"half_conversion_failures\":"<<half_conversion_failures<<",\"scale_permutation_failures\":"<<scale_permutation_failures<<",\"nonfinite_factors\":"<<nonfinite<<",\"prediction_values_checked\":"<<checked<<",\"prediction_failures\":"<<prediction_failures<<",\"max_prediction_abs_error\":"<<max_abs<<",\"max_prediction_bound_fraction\":"<<max_fraction<<",\"independent_train_squared_error_decimal\":\""<<train_error<<"\",\"independent_initial_train_squared_error_decimal\":\""<<initial_error<<"\",\"independent_heldout_RMSE_decimal\":\""<<rmse<<"\",\"changed_initial_factors\":"<<(changed?"true":"false")<<",\"LongDouble_mantissa_bits\":"<<std::numeric_limits<long double>::digits<<",\"LongDouble_storage_bytes\":"<<sizeof(long double)<<",\"prediction_bound\":\"gamma128(binary64)+gamma128(oracle)times_sumabs_products+8u64max(1,abs(sum)); source-modelFP32scale/permutationandhalfconversionbitexact\"}\n";return valid?0:1;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
